def from_pov(self, from_node):
    return self._reorient(from_node, None)

def _reorient(self, from_node, parent):
    if self.label == from_node:
        return Tree(self.label, [parent] if parent else [])
    new_children = []
    for child in self.children:
        result = child._reorient(from_node, self)
        if result is not None:
            new_children.append(result)
    return Tree(self.label, new_children)
```

