def path_to(self, from_node, to_node):
    pov = self.from_pov(from_node)
    return self._find_path(pov, to_node)

def _find_path(self, node, to_node, path):
    path = path + [node.label]
    if node.label == to_node:
        return path
    for child in node.children:
        result = self._find_path(child, to_node, path)
        if result is not None:
            return result
    return None
```

